const express = require('express');
const cors = require('cors');
const app = express();
// Não anuncia "X-Powered-By: Express" nas respostas
app.disable('x-powered-by');

// Atrás de um proxy/hospedagem que faz o HTTPS (TRUST_PROXY=1), confia no
// cabeçalho X-Forwarded-Proto para saber se o acesso original foi HTTPS.
if (process.env.TRUST_PROXY === '1') app.set('trust proxy', 1);

// HTTPS obrigatório em produção: recusa acessos em HTTP (senhas e tokens não
// podem trafegar sem criptografia) e avisa o navegador para sempre usar HTTPS.
app.use((req, res, next) => {
  if (req.secure) {
    res.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  } else if (process.env.NODE_ENV === 'production' && req.path !== '/') {
    return res.status(403).json({ error: 'Use HTTPS para acessar a API' });
  }
  next();
});

// importa o banco (executa criação das tabelas)
require('./database/db');

// middlewares globais
// libera o acesso para o app Flutter; expõe os cabeçalhos de paginação para a versão Web
app.use(cors({ exposedHeaders: ['X-Total-Count', 'X-Next-Offset'] }));
app.use(express.json());

// rota de healthcheck
app.get('/', (req, res) => {
  res.json({ status: 'ok', message: 'API rodando 🚀' });
});

// Política de privacidade pública (sem login): página e versão para o app
const politica = require('./legal/politicaPrivacidade');
app.get('/privacidade', (req, res) => res.type('html').send(politica.html()));
app.get('/privacidade.json', (req, res) => res.json(politica.json()));

// importar rotas
const userRoutes = require('./routes/userRoutes');
const authRoutes = require('./routes/authRoutes');
const categoryRoutes = require('./routes/categoryRoutes');
const incomeRoutes = require('./routes/incomeRoutes');
const expenseRoutes = require('./routes/expenseRoutes');
const goalRoutes = require('./routes/goalRoutes');
const dashboardRoutes = require('./routes/dashboardRoutes');
const extratoRoutes = require('./routes/extratoRoutes');

// registrar rotas com prefixo
app.use('/users', userRoutes);
app.use('/auth', authRoutes);
app.use('/categories', categoryRoutes);
app.use('/incomes', incomeRoutes);
app.use('/expenses', expenseRoutes);
app.use('/goals', goalRoutes);
app.use('/dashboard', dashboardRoutes);
app.use('/lancamentos', extratoRoutes);

// middleware 404 (rota não encontrada)
app.use((req, res) => {
  res.status(404).json({ error: 'Rota não encontrada' });
});

// middleware de tratamento de erro genérico
// eslint-disable-next-line no-unused-vars -- o Express exige os 4 parâmetros
app.use((err, req, res, next) => {
  // Erros do próprio cliente (ex.: JSON malformado, corpo grande demais) vêm
  // com status 4xx: responde esse status em vez de 500 (DEF-04).
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({ error: 'JSON inválido no corpo da requisição' });
  }
  const status = err.status || err.statusCode;
  if (status >= 400 && status < 500) {
    return res.status(status).json({ error: 'Requisição inválida' });
  }
  console.error(err);
  res.status(500).json({ error: 'Erro interno do servidor' });
});

module.exports = app;

const bcrypt = require('bcrypt');
const { emitirToken } = require('../utils/token');
const db = require('../database/db');
const { normalizeEmail, erroInterno } = require('../utils/validators');

// POST /auth/login
exports.login = (req, res) => {
  const { password } = req.body;
  const email = normalizeEmail(req.body.email);

  if (!email || !password) {
    return res.status(400).json({
      error: 'Email e password são obrigatórios'
    });
  }
  // Senha que não é texto (ex.: número) derrubava o bcrypt com erro 500 (DEF-03).
  if (typeof email !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Email e password devem ser texto' });
  }

  db.get(
    `SELECT * FROM users WHERE lower(email) = ?`,
    [email],
    async (err, user) => {
      if (err) return erroInterno(res, err);
      if (!user) {
        return res.status(401).json({ error: 'Email ou senha inválidos' });
      }

      if (!process.env.JWT_SECRET) {
        console.error('JWT_SECRET não definido no .env');
        return res.status(500).json({
          error: 'Servidor sem JWT_SECRET configurado. Veja o .env.example.'
        });
      }

      try {
        const isValid = await bcrypt.compare(password, user.password);
        if (!isValid) {
          return res.status(401).json({ error: 'Email ou senha inválidos' });
        }

        const token = emitirToken(user);

        res.json({
          token,
          user: {
            id: user.id,
            name: user.name,
            email: user.email
          }
        });
      } catch (e) {
        erroInterno(res, e);
      }
    }
  );
};

const db = require('../database/db');
const dbAsync = require('../utils/dbAsync');
const { HttpError, handleError, erroInterno, isTexto } = require('../utils/validators');

// POST /categories
// Nome obrigatório (até 50 caracteres) e sem repetir, para o mesmo usuário e tipo.
exports.create = async (req, res) => {
  try {
    const { type } = req.body;
    if (!req.body.name || !type) throw new HttpError(400, 'name e type são obrigatórios');
    if (!['income', 'expense'].includes(type)) {
      throw new HttpError(400, "type deve ser 'income' ou 'expense'");
    }
    if (!isTexto(req.body.name, 50)) {
      throw new HttpError(400, 'name deve ser um texto de até 50 caracteres');
    }
    const name = req.body.name.trim();

    const existente = await dbAsync.get(
      `SELECT id FROM categories WHERE user_id = ? AND type = ? AND lower(name) = lower(?)`,
      [req.userId, type, name]
    );
    if (existente) throw new HttpError(409, 'Já existe uma categoria com esse nome');

    const { lastID } = await dbAsync.run(
      `INSERT INTO categories (name, type, user_id) VALUES (?, ?, ?)`,
      [name, type, req.userId]
    );
    res.status(201).json({ id: lastID, name, type, user_id: req.userId });
  } catch (err) {
    handleError(res, err);
  }
};

// GET /categories
exports.list = (req, res) => {
  const { type } = req.query;

  let sql = `SELECT * FROM categories WHERE user_id = ?`;
  const params = [req.userId];

  if (type) {
    sql += ` AND type = ?`;
    params.push(type);
  }

  sql += ` ORDER BY name ASC`;

  db.all(sql, params, (err, rows) => {
    if (err) return erroInterno(res, err);
    res.json(rows);
  });
};

// DELETE /categories/:id
// Categoria com lançamentos não pode ser apagada (despesas exigem
// categoria). Responde 409 com mensagem clara em vez de erro do SQLite.
exports.remove = async (req, res) => {
  try {
    const { id } = req.params;

    const cat = await dbAsync.get(
      `SELECT id FROM categories WHERE id = ? AND user_id = ?`,
      [id, req.userId]
    );
    if (!cat) throw new HttpError(404, 'Categoria não encontrada');

    const uso = await dbAsync.get(
      `SELECT
         (SELECT COUNT(*) FROM incomes  WHERE category_id = ? AND user_id = ?) +
         (SELECT COUNT(*) FROM expenses WHERE category_id = ? AND user_id = ?) AS total`,
      [id, req.userId, id, req.userId]
    );
    if (uso.total > 0) {
      throw new HttpError(
        409,
        `Categoria em uso por ${uso.total} lançamento(s). Mova ou exclua esses lançamentos antes.`
      );
    }

    await dbAsync.run(`DELETE FROM categories WHERE id = ? AND user_id = ?`, [id, req.userId]);
    res.status(204).send();
  } catch (err) {
    handleError(res, err);
  }
};

const db = require('../database/db');
const { isValidMonth, erroInterno } = require('../utils/validators');
const { inicioDoMesSeguinte } = require('../utils/paginacao');

/**
 * GET /dashboard
 * Retorna o resumo financeiro do usuário logado:
 * saldo, totais, gastos/receitas por categoria e evolução mensal.
 *
 * Query params opcionais:
 *   ?month=2026-07  -> filtra os totais e categorias por mês (YYYY-MM)
 */
exports.summary = (req, res) => {
  const userId = req.userId;
  const { month } = req.query;

  if (month !== undefined && !isValidMonth(month)) {
    return res.status(400).json({ error: 'month deve estar no formato AAAA-MM' });
  }

  // Filtro de mês opcional, por faixa de datas para usar o índice (user_id, date)
  const monthFilter = month ? ` AND date >= ? AND date < ?` : '';
  const monthParams = month ? [`${month}-01`, inicioDoMesSeguinte(month)] : [];

  const queries = {
    totalIncomes: {
      sql: `SELECT ROUND(COALESCE(SUM(amount), 0), 2) AS total FROM incomes
            WHERE user_id = ?${monthFilter}`,
      params: [userId, ...monthParams]
    },
    totalExpenses: {
      sql: `SELECT ROUND(COALESCE(SUM(amount), 0), 2) AS total FROM expenses
            WHERE user_id = ?${monthFilter}`,
      params: [userId, ...monthParams]
    },
    expensesByCategory: {
      sql: `SELECT COALESCE(c.name, 'Sem categoria') AS category,
                   ROUND(SUM(e.amount), 2) AS total
            FROM expenses e
            LEFT JOIN categories c ON c.id = e.category_id
            WHERE e.user_id = ?${monthFilter.replace(/date/g, 'e.date')}
            GROUP BY c.name
            ORDER BY total DESC`,
      params: [userId, ...monthParams]
    },
    incomesByCategory: {
      sql: `SELECT COALESCE(c.name, 'Sem categoria') AS category,
                   ROUND(SUM(i.amount), 2) AS total
            FROM incomes i
            LEFT JOIN categories c ON c.id = i.category_id
            WHERE i.user_id = ?${monthFilter.replace(/date/g, 'i.date')}
            GROUP BY c.name
            ORDER BY total DESC`,
      params: [userId, ...monthParams]
    },
    monthly: {
      sql: `SELECT month, ROUND(SUM(incomes), 2) AS incomes, ROUND(SUM(expenses), 2) AS expenses
            FROM (
              SELECT strftime('%Y-%m', date) AS month, amount AS incomes, 0 AS expenses
              FROM incomes WHERE user_id = ?
              UNION ALL
              SELECT strftime('%Y-%m', date) AS month, 0 AS incomes, amount AS expenses
              FROM expenses WHERE user_id = ?
            )
            GROUP BY month
            ORDER BY month ASC`,
      params: [userId, userId]
    }
  };

  const result = {};
  const keys = Object.keys(queries);
  let pending = keys.length;
  let responded = false;

  const fail = (err) => {
    if (!responded) {
      responded = true;
      erroInterno(res, err);
    }
  };

  keys.forEach((key) => {
    const { sql, params } = queries[key];

    if (key === 'totalIncomes' || key === 'totalExpenses') {
      db.get(sql, params, (err, row) => {
        if (err) return fail(err);
        result[key] = row.total;
        if (--pending === 0) finish();
      });
    } else {
      db.all(sql, params, (err, rows) => {
        if (err) return fail(err);
        result[key] = rows;
        if (--pending === 0) finish();
      });
    }
  });

  function finish() {
    if (responded) return;
    responded = true;
    res.json({
      // Somas e saldo arredondados para centavos (DEF-01): antes 0,10 + 0,20 − 0,30
      // dava 5,55e-17 em vez de 0.
      balance: Math.round((result.totalIncomes - result.totalExpenses) * 100) / 100 || 0,
      total_incomes: result.totalIncomes,
      total_expenses: result.totalExpenses,
      expenses_by_category: result.expensesByCategory,
      incomes_by_category: result.incomesByCategory,
      monthly: result.monthly
    });
  }
};

const dbAsync = require('../utils/dbAsync');
const {
  HttpError,
  isPositiveNumber,
  isNonNegativeNumber,
  handleError,
} = require('../utils/validators');

/** Ícones aceitos (mesmas chaves do app). */
const ICONES = ['flag', 'wallet', 'home', 'car', 'flight', 'phone', 'school', 'laptop', 'star', 'trend'];
const ICONE_PADRAO = 'flag';

function validarIcone(icon) {
  if (!ICONES.includes(icon)) {
    throw new HttpError(400, `icon deve ser um destes: ${ICONES.join(', ')}`);
  }
}

// POST /goals
exports.create = async (req, res) => {
  try {
    const { title, target_amount, current_amount, icon } = req.body;

    if (typeof title !== 'string' || !title.trim()) {
      throw new HttpError(400, 'title é obrigatório');
    }
    if (title.trim().length > 100) throw new HttpError(400, 'title deve ter até 100 caracteres');
    if (!isPositiveNumber(target_amount)) {
      throw new HttpError(400, 'target_amount deve ser um número positivo');
    }
    const atual = current_amount === undefined || current_amount === null ? 0 : current_amount;
    if (!isNonNegativeNumber(atual)) {
      throw new HttpError(400, 'current_amount deve ser um número maior ou igual a zero');
    }
    const icone = icon === undefined || icon === null ? ICONE_PADRAO : icon;
    validarIcone(icone);

    const { lastID } = await dbAsync.run(
      `INSERT INTO goals (title, target_amount, current_amount, icon, user_id)
       VALUES (?, ?, ?, ?, ?)`,
      [title.trim(), target_amount, atual, icone, req.userId]
    );

    res.status(201).json({
      id: lastID,
      title: title.trim(),
      target_amount,
      current_amount: atual,
      icon: icone,
      user_id: req.userId,
    });
  } catch (err) {
    handleError(res, err);
  }
};

// GET /goals
exports.list = async (req, res) => {
  try {
    const rows = await dbAsync.all(
      `SELECT * FROM goals WHERE user_id = ? ORDER BY created_at DESC, id DESC`,
      [req.userId]
    );
    res.json(rows);
  } catch (err) {
    handleError(res, err);
  }
};

// PATCH /goals/:id - atualiza progresso, título, valor alvo e ícone
exports.update = async (req, res) => {
  try {
    const { current_amount, title, target_amount, icon } = req.body;
    const fields = [];
    const params = [];

    if (current_amount !== undefined) {
      if (!isNonNegativeNumber(current_amount)) {
        throw new HttpError(400, 'current_amount deve ser um número maior ou igual a zero');
      }
      fields.push('current_amount = ?');
      params.push(current_amount);
    }
    if (title !== undefined) {
      if (typeof title !== 'string' || !title.trim()) {
        throw new HttpError(400, 'title não pode ser vazio');
      }
      if (title.trim().length > 100) throw new HttpError(400, 'title deve ter até 100 caracteres');
      fields.push('title = ?');
      params.push(title.trim());
    }
    if (target_amount !== undefined) {
      if (!isPositiveNumber(target_amount)) {
        throw new HttpError(400, 'target_amount deve ser um número positivo');
      }
      fields.push('target_amount = ?');
      params.push(target_amount);
    }
    if (icon !== undefined) {
      validarIcone(icon);
      fields.push('icon = ?');
      params.push(icon);
    }

    if (fields.length === 0) throw new HttpError(400, 'Nenhum campo para atualizar');

    params.push(req.params.id, req.userId);
    const { changes } = await dbAsync.run(
      `UPDATE goals SET ${fields.join(', ')} WHERE id = ? AND user_id = ?`,
      params
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');

    res.json({ message: 'Meta atualizada' });
  } catch (err) {
    handleError(res, err);
  }
};

// POST /goals/:id/aportes - soma um aporte ao valor guardado.
// A soma é feita no próprio UPDATE, então dois aportes simultâneos
// não sobrescrevem um ao outro.
exports.aportar = async (req, res) => {
  try {
    const { amount } = req.body;
    if (!isPositiveNumber(amount)) {
      throw new HttpError(400, 'amount deve ser um número positivo');
    }

    const { changes } = await dbAsync.run(
      // ROUND(…, 2): sem resíduo de ponto flutuante (0,10 + 0,20 = 0,30) (DEF-01)
      `UPDATE goals SET current_amount = ROUND(COALESCE(current_amount, 0) + ?, 2)
       WHERE id = ? AND user_id = ?`,
      [amount, req.params.id, req.userId]
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');

    const meta = await dbAsync.get(
      `SELECT * FROM goals WHERE id = ? AND user_id = ?`,
      [req.params.id, req.userId]
    );
    res.json(meta);
  } catch (err) {
    handleError(res, err);
  }
};

// DELETE /goals/:id
exports.remove = async (req, res) => {
  try {
    const { changes } = await dbAsync.run(
      `DELETE FROM goals WHERE id = ? AND user_id = ?`,
      [req.params.id, req.userId]
    );
    if (changes === 0) throw new HttpError(404, 'Meta não encontrada');
    res.status(204).send();
  } catch (err) {
    handleError(res, err);
  }
};

const dbAsync = require('../utils/dbAsync');
const {
  HttpError,
  isPositiveNumber,
  isValidDate,
  assertCategory,
  handleError,
} = require('../utils/validators');
const {
  MIN_PARCELAS,
  MAX_PARCELAS,
  dividirValor,
  datasParcelas,
  novoGrupo,
} = require('../utils/parcelas');
const { periodo, pagina } = require('../utils/paginacao');

/**
 * Fábrica dos controllers de receitas (/incomes) e despesas (/expenses).
 * As duas tabelas têm a mesma estrutura; a diferença é que a despesa
 * exige categoria e a receita aceita ficar sem.
 *
 * @param {object} cfg
 * @param {'incomes'|'expenses'} cfg.table
 * @param {'income'|'expense'} cfg.type     tipo de categoria aceito
 * @param {boolean} cfg.categoryRequired
 * @param {string} cfg.label                 "Receita" / "Despesa"
 */
module.exports = function lancamentoController({ table, type, categoryRequired, label }) {
  const notFound = `${label} não encontrada`;

  /** Valida categoria (se veio) e devolve o valor a gravar. */
  async function resolveCategory(categoryId, userId) {
    if (categoryId === undefined || categoryId === null) {
      if (categoryRequired) throw new HttpError(400, 'category_id é obrigatório');
      return null;
    }
    await assertCategory(categoryId, userId, type);
    return categoryId;
  }

  /**
   * Cria uma compra/receita parcelada: `amount` é o valor TOTAL, dividido
   * em `n` lançamentos mensais ligados pelo mesmo parcela_grupo.
   *
   * Todas as parcelas vão num ÚNICO INSERT (várias linhas), que o SQLite grava
   * de forma atômica: ou entram todas, ou nenhuma. Antes era usado BEGIN/COMMIT
   * na conexão única compartilhada por todas as requisições, e compras
   * parceladas simultâneas falhavam com erro 500 (DEF-16).
   */
  async function criarParcelado(req, res, { amount, description, date, categoryId, n }) {
    const grupo = novoGrupo();
    const valores = dividirValor(amount, n);
    const datas = datasParcelas(date, n);

    const linhas = valores.map(() => '(?, ?, ?, ?, 1, ?, ?, ?, ?)').join(', ');
    const params = valores.flatMap((v, i) => [
      v, description || null, datas[i], categoryId, req.userId, grupo, i + 1, n,
    ]);
    await dbAsync.run(
      `INSERT INTO ${table}
         (amount, description, date, category_id, parcelado, user_id,
          parcela_grupo, parcela_numero, parcela_total)
       VALUES ${linhas}`,
      params
    );
    const ids = await dbAsync.all(
      `SELECT id, parcela_numero FROM ${table} WHERE parcela_grupo = ? ORDER BY parcela_numero`,
      [grupo]
    );
    const criadas = ids.map((r, i) => ({
      id: r.id, amount: valores[i], date: datas[i], parcela_numero: r.parcela_numero,
    }));

    res.status(201).json({
      ...criadas[0],
      description: description || null,
      category_id: categoryId,
      parcelado: 1,
      user_id: req.userId,
      parcela_grupo: grupo,
      parcela_total: n,
      valor_total: amount,
      parcelas: criadas,
    });
  }

  // POST /
  // Campo opcional `parcelas` (2 a 48): divide `amount` em parcelas mensais.
  async function create(req, res) {
    try {
      const { amount, description, date, category_id, parcelado, parcelas } = req.body;

      if (amount === undefined || amount === null || !date) {
        throw new HttpError(400, 'amount e date são obrigatórios');
      }
      if (!isPositiveNumber(amount)) {
        throw new HttpError(400, 'amount deve ser um número positivo');
      }
      if (!isValidDate(date)) {
        throw new HttpError(400, 'date deve estar no formato AAAA-MM-DD');
      }
      if (description != null && (typeof description !== 'string' || description.length > 200)) {
        throw new HttpError(400, 'description deve ser um texto de até 200 caracteres');
      }
      if (parcelas !== undefined && parcelas !== null && parcelas !== 1) {
        if (!Number.isInteger(parcelas) || parcelas < MIN_PARCELAS || parcelas > MAX_PARCELAS) {
          throw new HttpError(
            400,
            `parcelas deve ser um número inteiro de ${MIN_PARCELAS} a ${MAX_PARCELAS}`
          );
        }
        if (amount < parcelas * 0.01) {
          throw new HttpError(400, 'amount é pequeno demais para tantas parcelas');
        }
      }
      const categoryId = await resolveCategory(category_id, req.userId);

      if (Number.isInteger(parcelas) && parcelas >= MIN_PARCELAS) {
        return await criarParcelado(req, res, {
          amount, description, date, categoryId, n: parcelas,
        });
      }

      const { lastID } = await dbAsync.run(
        `INSERT INTO ${table} (amount, description, date, category_id, parcelado, user_id)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [amount, description || null, date, categoryId, parcelado ? 1 : 0, req.userId]
      );

      res.status(201).json({
        id: lastID,
        amount,
        description: description || null,
        date,
        category_id: categoryId,
        parcelado: parcelado ? 1 : 0,
        user_id: req.userId,
      });
    } catch (err) {
      handleError(res, err);
    }
  }

  // GET /   aceita ?month=AAAA-MM, ?from=, ?to= (AAAA-MM-DD), ?limit= e ?offset=
  //
  // A lista é PAGINADA: devolve no máximo `limit` itens (padrão 500, máximo
  // 1000), do mais recente para o mais antigo. O total de itens do filtro vai no
  // cabeçalho X-Total-Count e, quando há mais páginas, X-Next-Offset traz o
  // offset da próxima. Antes a rota devolvia todos os lançamentos do usuário de
  // uma vez (12 MB para quem tem 50 mil).
  async function list(req, res) {
    try {
      const filtro = periodo(req.query, 't.date');
      const { limit, offset } = pagina(req.query);
      const params = [req.userId, ...filtro.params];

      const [{ n }, rows] = await Promise.all([
        dbAsync.get(`SELECT COUNT(*) AS n FROM ${table} t WHERE t.user_id = ?${filtro.sql}`, params),
        limit === 0
          ? Promise.resolve([])
          : dbAsync.all(
            `SELECT t.*, c.name AS category_name
             FROM ${table} t
             LEFT JOIN categories c ON c.id = t.category_id
             WHERE t.user_id = ?${filtro.sql}
             ORDER BY t.date DESC, t.id DESC
             LIMIT ? OFFSET ?`,
            [...params, limit, offset]
          ),
      ]);

      res.set('X-Total-Count', String(n));
      if (offset + rows.length < n && limit > 0) res.set('X-Next-Offset', String(offset + rows.length));
      res.json(rows);
    } catch (err) {
      handleError(res, err);
    }
  }

  // PUT /:id
  async function update(req, res) {
    try {
